package com.pulsbreath.android;

import android.Manifest;import android.app.Activity;import android.content.*;import android.content.pm.PackageManager;import android.net.*;import android.net.wifi.*;import android.os.*;import android.view.*;import android.widget.*;
import com.pulsbreath.core.MeasurementPipeline;import com.pulsbreath.core.MathProcessor;
import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.concurrent.*;

public final class MainActivity extends Activity {
 private final MeasurementPipeline pipeline=new MeasurementPipeline();private AndroidDatabase db;private AndroidBleClient ble;
 private TextView status,pulse,breath,distance,target;private EditText ssid;private Button connectBle,connectWifi,disconnect;
 private ConnectivityManager cm;private ConnectivityManager.NetworkCallback networkCallback;private Network sensorNetwork;private ScheduledExecutorService wifiPoller;private boolean wifiMode;
 @Override public void onCreate(Bundle b){super.onCreate(b);db=new AndroidDatabase(this);cm=(ConnectivityManager)getSystemService(CONNECTIVITY_SERVICE);buildUi();}
 private void buildUi(){LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(28,28,28,28);ScrollView scroll=new ScrollView(this);scroll.addView(root);TextView title=new TextView(this);title.setText("PulseBreath — MR60BHA2");title.setTextSize(23);root.addView(title);
 status=label(root,"Статус: не підключено");target=label(root,"Людина в зоні: —");pulse=label(root,"Пульс: —");breath=label(root,"Дихання: —");distance=label(root,"Відстань: —");
 TextView info=new TextView(this);info.setText("Виберіть один спосіб підключення. Для Wi-Fi спочатку введіть назву точки доступу ESP32 (MR60BHA2-XXXX). Пароль: MR60setup.");root.addView(info);
 ssid=new EditText(this);ssid.setSingleLine(true);ssid.setHint("SSID, наприклад MR60BHA2-A1B2");root.addView(ssid);
 connectBle=new Button(this);connectBle.setText("Підключити через Bluetooth LE");connectBle.setOnClickListener(v->startBle());root.addView(connectBle);
 connectWifi=new Button(this);connectWifi.setText("Підключити через Wi-Fi сенсора");connectWifi.setOnClickListener(v->startWifi());root.addView(connectWifi);
 disconnect=new Button(this);disconnect.setText("Відключити");disconnect.setOnClickListener(v->stopAll());root.addView(disconnect);
 TextView note=new TextView(this);note.setText("Пульс, дихання та відстань проходять через спільний MathProcessor. Підсумок зберігається в SQLite щохвилини. Показники є експериментальними й не замінюють медичну діагностику.");root.addView(note);setContentView(scroll);}
 private TextView label(LinearLayout parent,String text){TextView t=new TextView(this);t.setText(text);t.setTextSize(17);t.setPadding(0,12,0,12);parent.addView(t);return t;}
 private void startBle(){stopAll();if(Build.VERSION.SDK_INT>=31&&(checkSelfPermission(Manifest.permission.BLUETOOTH_SCAN)!=PackageManager.PERMISSION_GRANTED||checkSelfPermission(Manifest.permission.BLUETOOTH_CONNECT)!=PackageManager.PERMISSION_GRANTED)){requestPermissions(new String[]{Manifest.permission.BLUETOOTH_SCAN,Manifest.permission.BLUETOOTH_CONNECT},10);return;}pipeline.reset();ble=new AndroidBleClient(this,new AndroidBleClient.Listener(){public void onStatus(String s){runOnUiThread(()->status.setText(s));}public void onJson(String j){acceptJson(j);}});ble.start();}
 private void startWifi(){if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.NEARBY_WIFI_DEVICES)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.NEARBY_WIFI_DEVICES},11);return;}String name=ssid.getText().toString().trim();if(name.isEmpty()){status.setText("Введіть SSID точки доступу ESP32");return;}stopAll();pipeline.reset();if(Build.VERSION.SDK_INT<29){status.setText("Автоматичне підключення до Wi-Fi підтримується на Android 10+. Підключіться вручну до "+name+" (пароль MR60setup), потім повторіть.");return;}wifiMode=true;WifiNetworkSpecifier spec=new WifiNetworkSpecifier.Builder().setSsid(name).setWpa2Passphrase("MR60setup").build();NetworkRequest request=new NetworkRequest.Builder().addTransportType(NetworkCapabilities.TRANSPORT_WIFI).removeCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET).setNetworkSpecifier(spec).build();networkCallback=new ConnectivityManager.NetworkCallback(){@Override public void onAvailable(Network n){sensorNetwork=n;runOnUiThread(()->status.setText("Wi-Fi сенсора підключено; опитування API…"));startPolling(n);}@Override public void onUnavailable(){runOnUiThread(()->status.setText("Не вдалося підключитися. Перевірте SSID і пароль MR60setup."));}@Override public void onLost(Network n){if(sensorNetwork==n){sensorNetwork=null;runOnUiThread(()->status.setText("Wi-Fi сенсора втрачено"));}}};try{cm.requestNetwork(request,networkCallback);}catch(Exception e){status.setText("Помилка Wi-Fi: "+e.getMessage());}}
 private void startPolling(Network n){if(wifiPoller!=null)wifiPoller.shutdownNow();wifiPoller=Executors.newSingleThreadScheduledExecutor();wifiPoller.scheduleWithFixedDelay(()->{try{HttpURLConnection c=(HttpURLConnection)n.openConnection(new URL("http://192.168.4.1/api/sensor"));c.setConnectTimeout(2500);c.setReadTimeout(2500);c.setRequestMethod("GET");try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buffer=new byte[2048];int count;while((count=in.read(buffer))!=-1)out.write(buffer,0,count);acceptJson(out.toString(StandardCharsets.UTF_8));}finally{c.disconnect();}}catch(Exception e){runOnUiThread(()->status.setText("Wi-Fi API: "+e.getMessage()));}},0,1,TimeUnit.SECONDS);}
 private void acceptJson(String json){try{MeasurementPipeline.Result r=pipeline.acceptJson(json);MathProcessor.Measurement m=r.live;runOnUiThread(()->{status.setText("Дані отримано · запис: "+r.packet.recording);target.setText("Людина в зоні: "+(r.packet.target?"так":"ні"));pulse.setText("Пульс: "+(m.pulseValid?String.format(java.util.Locale.getDefault(),"%.1f уд/хв",m.pulse):"очікування валідних даних"));breath.setText("Дихання: "+(m.breathValid?String.format(java.util.Locale.getDefault(),"%.1f вдихів/хв",m.breath):"очікування валідних даних"));distance.setText("Відстань: "+(m.distanceValid?String.format(java.util.Locale.getDefault(),"%.1f см",m.distanceCm):"недоступна"));});if(r.completedMinute!=null)db.save(r.completedMinute);}catch(Exception e){runOnUiThread(()->status.setText("Помилка JSON/обробки: "+e.getMessage()));}}
 private void stopAll(){if(ble!=null){ble.stop();ble=null;}if(wifiPoller!=null){wifiPoller.shutdownNow();wifiPoller=null;}if(networkCallback!=null){try{cm.unregisterNetworkCallback(networkCallback);}catch(Exception ignored){}networkCallback=null;}sensorNetwork=null;wifiMode=false;if(status!=null)status.setText("Статус: не підключено");}
 @Override protected void onDestroy(){stopAll();if(db!=null)db.close();super.onDestroy();}
 @Override public void onRequestPermissionsResult(int req,String[] perms,int[] results){super.onRequestPermissionsResult(req,perms,results);if(req==11){boolean ok=results.length>0&&results[0]==PackageManager.PERMISSION_GRANTED;if(ok)startWifi();else status.setText("Для Wi-Fi потрібен дозвіл Nearby Wi-Fi Devices.");return;}if(req==10){boolean ok=true;for(int r:results)if(r!=PackageManager.PERMISSION_GRANTED)ok=false;if(ok)startBle();else status.setText("Для BLE потрібні дозволи Bluetooth Scan і Connect.");}}
}
